-- Garages sign their partner agreement on the onboarding page, give their GSTIN, and upload their photos there. This adds:
--   garages.gstin (optional, format-checked) and garages.agreed_rate (the Bronze rate Admin sets before the link is sent);
--   the agreement terms are seeded with the client's text, so every signature snapshots the exact wording and numbers that were shown;
--   partner_agreements: one row per online signature (name typed, time, hashed IP and browser, terms version, the full terms and plan numbers at that moment);
--   service-role RPCs partner_agreement_data / partner_agreement_sign for the partner-onboard function, and admin RPCs admin_agreement_signed / garage_agreed_rate_set.
-- Additive. A GSTIN of a proprietor contains their PAN, so it is only ever returned to owner/admin and to the garage's own onboarding link.
-- Rollback: drop function public.partner_agreement_data(uuid), public.partner_agreement_sign(uuid, text, text, integer, text, text), public.admin_agreement_signed(uuid), public.garage_agreed_rate_set(uuid, numeric); drop table public.partner_agreements; alter table public.garages drop column gstin, drop column agreed_rate; re-run admin_garage_get from 20270136000000_agreement_autofill.sql.
alter table public.garages add column if not exists gstin text check (gstin is null or gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$');
alter table public.garages add column if not exists agreed_rate numeric(5,2) check (agreed_rate is null or (agreed_rate > 0 and agreed_rate <= 100));

insert into public.agreement_terms (id, doc, version, updated_at) values (1, $agr${"part_a":[{"title":"Parties and status","text":"NOVA VENTURES, brand Mechanix Pro (the Company), and the garage named in the tier terms (the Garage). The Garage is an independent business, not an employee, agent or partner of the Company. The Garage pays its own staff, taxes and dues. The Company introduces Jobs through its Platform (website, Crew and Admin desks, garage and mechanic apps) and acts as a service aggregator."},{"title":"Onboarding","text":"Before the first Job the Garage uploads: owner’s Aadhaar and PAN, garage photos, any shop or trade licence, and this signed Agreement. The Company may approve or reject any application without giving a reason. A false or forged document means immediate termination and, where the law requires, a report to the authorities. The Garage keeps its registrations and insurance valid and informs the Company within 7 days of any change. The Garage does not submit KYC or documents for its mechanics. The Garage alone is fully responsible for every mechanic and worker it uses, including their conduct, work, safety and pay, and for any loss, damage, theft or claim they cause. Any such amount is the Garage’s liability under clause 13."},{"title":"App access","text":"The Garage keeps its app link and PIN private and is responsible for all use of them. A Job not accepted or declined within 15 minutes may be reassigned, without penalty."},{"title":"Quote first","text":"No chargeable work starts until the customer approves an itemised quote on the Platform. Extra work needs a revised quote and fresh approval. The Garage never charges for unapproved work. Parts must be genuine or equivalent quality, as stated in the quote. Never fit a used part and charge for a new one."},{"title":"Code and photos","text":"The Garage enters the customer’s one-time handover code in the app before starting work. Five wrong tries lock the code, and the Garage must call the Company. The Garage takes clear photos at pickup (all sides, odometer, existing damage), at arrival at the garage, when work is complete (including replaced parts) and at delivery. The Garage sets an estimated completion date when the vehicle arrives. All photos and records belong to the Company’s Job record and may be used to settle disputes."},{"title":"Standards","text":"The Garage works with reasonable skill and care, with trained people and a safe workshop. It follows the Motor Vehicles Act 1988, does not road-test without a licensed driver, and does not use child labour. It follows fire, safety, labour and environmental laws, and there is no bribery, harassment or pressure to buy extra work."},{"title":"Warranty","text":"Normal service work is warranted for 30 days or 500 km, whichever comes first. Engine repair work is warranted for 6 months. Defects in either are redone free of charge within 3 working days of notice. Accident, misuse, neglect and third-party work are excluded."},{"title":"Custody","text":"From pickup until delivery the vehicle is the Garage’s responsibility. The Garage is liable for loss, theft or damage to the vehicle and its accessories up to its declared value, unless caused by something outside its control that it could not reasonably have prevented. The pickup, arrival, ready and delivery photos are the main evidence. The vehicle must be kept locked and safe overnight and must not be lent, sold or used for anything other than the Job. The Garage should carry garage keeper’s liability insurance."},{"title":"Payments","text":"The Company collects the customer’s payment and issues the final bill. The customer’s confirmation fee (Rs 49, Rs 69 or Rs 99, including GST) is adjusted in the final bill. Commission is calculated only on the bill’s base price, excluding GST. All GST collected from the customer goes directly to the Company, which files and pays it. The Garage cannot claim any GST, input credit or GST invoice for Jobs, and cannot ask the Company to file GST for it. Any cash or UPI collected directly by the Garage is recorded in the app, and the Company’s share is paid to the Company within 24 hours of collection. Taking payment outside the Platform to avoid the Company’s share is a ground for immediate termination."},{"title":"Payout","text":"The Company pays the Garage by bank transfer to the verified account one day after Razorpay settles the customer’s payment to the Company (settlement date plus 1 day), for Jobs that are delivered, paid, photo-complete and undisputed. Razorpay’s settlement timing applies. The payout is the bill’s base price less commission and any deductions; GST is never payable to the Garage. If that day is a bank holiday, the payout is made on the next working day."},{"title":"Deductions and holds","text":"The Company may deduct from payouts the commission, refunds paid because of the Garage’s work, chargebacks, reversed payments and penalties. Penalties: no-show after accepting {{pen_noshow}}; cancelling after accepting without valid reason {{pen_cancel}}; estimated date not set within 4 hours of arrival {{pen_date}}. Penalties are capped at {{pen_cap}}% of any one payout. For a disputed Job the Company may hold up to 10% of that Job’s payout for up to 30 days."},{"title":"Customer data","text":"The Garage uses customer details only for the open Job assigned to it. It does not contact the customer outside the Job, advertise to them, take them to another platform or share their details. It follows the Digital Personal Data Protection Act 2023, reports any leak to the Company within 72 hours, and deletes customer data when the Job ends unless the law requires otherwise. The Company uses the Garage’s identity documents only for verification and compliance and deletes them after exit, except what the law requires it to keep."},{"title":"Indemnity and liability","text":"The Garage compensates the Company for losses, claims and costs caused by its negligence, breach of this Agreement or the law, or the acts of its staff and mechanics. The Company’s total liability to the Garage is limited to payouts due and unpaid. Neither side is liable for indirect or consequential loss."},{"title":"Quality suspension","text":"The Company may pause the Garage’s access for repeated complaints, poor ratings, missing photos or dates, no-shows, unsafe work or breach, and will give the reason. Access is restored once the problem is fixed."},{"title":"Immediate termination","text":"The Company may terminate immediately for fraud, forged documents, theft or damage of a vehicle, risk to a customer, payments taken outside the Platform, misuse of customer data, or loss of a required licence. On termination the Garage completes Jobs in progress and returns all vehicles, and the Company pays what is due."},{"title":"Confidentiality and non-solicit","text":"Commission rates, customer data and the Platform’s workings are confidential during the Agreement and for 3 years after. For 12 months after exit the Garage will not solicit or serve, outside the Platform, any customer it first met through the Platform in a way that avoids the Company’s share. Ordinary walk-in business is not restricted."},{"title":"Law and disputes","text":"Indian law governs. Disputes are discussed for 15 days, then go to arbitration under the Arbitration and Conciliation Act 1996 before a sole arbitrator, seated in Bengaluru, in English. The courts at Bengaluru have exclusive jurisdiction for anything arbitration cannot decide."},{"title":"General","text":"This Part A, the tier terms and the app terms are the whole agreement. Changes must be in writing, except that the Company may update the app terms on 30 days’ notice. The Garage may not transfer its rights or sub-contract the work without the Company’s written consent. Neither side is liable for delay caused by events outside its control, which does not excuse payment obligations. Notices are given by email or in the app. A signed scan is valid. This Agreement is executed on stamp paper of proper value under the Karnataka Stamp Act, and the Company bears the stamp duty."}],"part_b":{"bronze":[{"title":"Tier","text":"Bronze: no deposit, commission-based only."},{"title":"Commission","text":"The Company sets the Garage’s commission rate in the Admin panel according to the Garage’s system profile (location, capacity, rating and service type). The rate shown in the Garage’s profile and Settlement Statement at onboarding is the agreed rate. The Company may change it on 30 days’ notice in the app. If the Garage does not accept the new rate, it may exit on 30 days’ notice. Commission applies to the overall bill base price (labour, service and parts), excluding GST."},{"title":"Jobs","text":"The Company promises no minimum number of Jobs. The Garage need not accept every Job."},{"title":"Deposit","text":"None."},{"title":"Term","text":"12 months from signing. It does not renew automatically: a new agreement is prepared and signed every year, and the Garage’s access ends on expiry if the new agreement is not signed. Either side may exit on 30 days’ written notice. Upgrade to Silver or Gold is possible by signing that tier’s agreement."},{"title":"Agreed rate at signing","text":"{{rate}} %"}],"silver":[{"title":"Tier","text":"Silver: non-refundable deposit, fixed commission, volume band of {{min}} to {{max}} orders per month."},{"title":"Deposit","text":"The Garage pays {{deposit}} to the Company before activation, by bank transfer, and receives a receipt. The deposit covers 3 months (the Silver Term). It is non-refundable and earns no interest."},{"title":"Commission","text":"{{rate}}% of the overall bill base price (labour, service and parts), excluding GST. Parts are charged at cost with a Garage margin capped at 10%, itemised in the quote. Commission is deducted from each payout and summarised in a monthly statement."},{"title":"Order band","text":"The Company will use reasonable efforts to route {{min}} to {{max}} orders a month to the Garage, subject to customer demand, location and the Garage’s ratings. This is a target band, not a guarantee. The Garage confirms it has capacity for up to {{max}} orders a month and will accept at least {{accept}}% of the Jobs assigned to it. If it falls below that, or its quality is poor for two consecutive months, the Company may move it to Bronze, with no refund of the deposit."},{"title":"No refund","text":"The deposit is non-refundable. The Company keeps it on expiry of the term, exit by either side, termination, or a move to Bronze."},{"title":"Term","text":"The deposit term is 3 months from activation and renews for further 3-month terms unless either side gives 15 days’ written notice before it ends. Each renewal keeps the same deposit, which need not be paid again. This Agreement lasts 12 months from signing and does not renew automatically: a new agreement is prepared and signed every year, and the deposit is non-refundable and carries over to it only if the new agreement says so. Either side may exit on 30 days’ written notice."}],"gold":[{"title":"Tier","text":"Gold: higher non-refundable deposit, lower commission, volume band of {{min}} to {{max}} orders per month, priority allocation."},{"title":"Deposit","text":"The Garage pays {{deposit}} to the Company before activation, by bank transfer, and receives a receipt. The deposit covers 3 months (the Gold Term). It is non-refundable and earns no interest."},{"title":"Commission","text":"{{rate}}% of the overall bill base price (labour, service and parts), excluding GST. Parts are charged at cost with a Garage margin capped at 10%, itemised in the quote. Commission is deducted from each payout and summarised in a monthly statement."},{"title":"Order band and priority","text":"The Company will use reasonable efforts to route {{min}} to {{max}} orders a month to the Garage, with priority over Bronze and Silver garages in the same area when ratings and availability allow. This is a target band, not a guarantee. The Garage confirms it has capacity for up to {{max}} orders a month and will accept at least {{accept}}% of the Jobs assigned to it. If it falls below that, or its quality is poor for two consecutive months, the Company may move it to Silver or Bronze, with no refund of any part of the deposit."},{"title":"No refund","text":"The deposit is non-refundable. The Company keeps it on expiry of the term, exit by either side, termination, or a move to Silver or Bronze."},{"title":"Term","text":"The deposit term is 3 months from activation and renews for further 3-month terms unless either side gives 15 days’ written notice before it ends. Each renewal keeps the same deposit, which need not be paid again. This Agreement lasts 12 months from signing and does not renew automatically: a new agreement is prepared and signed every year, and the deposit is non-refundable and carries over to it only if the new agreement says so. Either side may exit on 30 days’ written notice."}]},"vars":{"pen_noshow":300,"pen_cancel":200,"pen_date":100,"pen_cap":10,"accept_silver":70,"accept_gold":80}}$agr$::jsonb, 1, now()) on conflict (id) do nothing;
insert into public.agreement_terms_log (version, doc, note) select 1, doc, 'Original text' from public.agreement_terms where id = 1 and not exists (select 1 from public.agreement_terms_log);

create table if not exists public.partner_agreements (
  id uuid primary key default gen_random_uuid(),
  garage_id uuid not null references public.garages(id),
  tier text not null check (tier in ('bronze','silver','gold')),
  rate numeric(5,2) not null,
  deposit_amount numeric(12,2) not null default 0,
  orders_min integer, orders_max integer,
  terms_version integer not null,
  terms jsonb not null,
  garage jsonb not null,
  signed_name text not null,
  signed_at timestamptz not null default now(),
  ip_hash text, ua_hash text
);
create index if not exists partner_agreements_garage_idx on public.partner_agreements (garage_id, signed_at desc);
alter table public.partner_agreements enable row level security;

create or replace function public.partner_agreement_data(p_garage uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare g public.garages; pl public.partner_plans; t public.agreement_terms; s public.partner_agreements; r numeric;
begin
  select * into g from public.garages where id = p_garage and deleted_at is null; if not found then return null; end if;
  select * into pl from public.partner_plans where plan = g.plan;
  select * into t from public.agreement_terms where id = 1;
  select * into s from public.partner_agreements where garage_id = g.id order by signed_at desc limit 1;
  r := case when g.plan = 'bronze' then g.agreed_rate else pl.commission_pct end;
  return jsonb_build_object('garage', jsonb_build_object('code', g.code, 'name', g.name, 'legal_name', g.legal_name, 'owner_name', g.owner_name, 'mobile', g.mobile, 'address', g.address, 'landmark', g.landmark, 'pincode', g.pincode, 'city', g.city,
      'trade_id', g.trade_id, 'gstin', g.gstin, 'deposit_status', g.deposit_status, 'deposit_received_at', g.deposit_received_at),
    'tier', g.plan, 'plan', jsonb_build_object('commission_pct', pl.commission_pct, 'deposit_amount', pl.deposit_amount, 'orders_min', pl.orders_min, 'orders_max', pl.orders_max),
    'rate', r, 'ready', r is not null and t.id is not null, 'terms', jsonb_build_object('doc', t.doc, 'version', coalesce(t.version, 0)),
    'signed', case when s.id is null then null else jsonb_build_object('name', s.signed_name, 'at', s.signed_at, 'tier', s.tier) end);
end $$;

create or replace function public.partner_agreement_sign(p_garage uuid, p_name text, p_gstin text, p_terms_version integer, p_ip_hash text, p_ua_hash text) returns jsonb language plpgsql security definer set search_path = public as $$
declare g public.garages; pl public.partner_plans; t public.agreement_terms; nm text := btrim(coalesce(p_name, '')); gs text := nullif(upper(btrim(coalesce(p_gstin, ''))), ''); r numeric; new_id uuid;
begin
  select * into g from public.garages where id = p_garage and deleted_at is null for update; if not found then return jsonb_build_object('ok', false, 'error', 'This garage is not available.'); end if;
  if exists (select 1 from public.partner_agreements where garage_id = g.id) then return jsonb_build_object('ok', false, 'error', 'The agreement is already signed.'); end if;
  select * into t from public.agreement_terms where id = 1; if not found then return jsonb_build_object('ok', false, 'error', 'The agreement is not ready yet. Please try again later.'); end if;
  if p_terms_version is distinct from t.version then return jsonb_build_object('ok', false, 'error', 'The agreement was just updated. Reload the page and read it again.', 'stale', true); end if;
  select * into pl from public.partner_plans where plan = g.plan;
  r := case when g.plan = 'bronze' then g.agreed_rate else pl.commission_pct end;
  if r is null then return jsonb_build_object('ok', false, 'error', 'Your commission rate is not set yet. Mechanix Pro will confirm it and tell you.'); end if;
  if char_length(nm) < 3 or char_length(nm) > 80 or nm !~ '^[A-Za-z .''-]+$' then return jsonb_build_object('ok', false, 'error', 'Type your full name in letters.'); end if;
  if gs is not null and gs !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$' then return jsonb_build_object('ok', false, 'error', 'The GSTIN should be 15 letters and numbers, like 29ABCDE1234F1Z5. Leave it empty if you have none.'); end if;
  if gs is not null then update public.garages set gstin = gs where id = g.id; g.gstin := gs; end if;
  insert into public.partner_agreements (garage_id, tier, rate, deposit_amount, orders_min, orders_max, terms_version, terms, garage, signed_name, ip_hash, ua_hash)
    values (g.id, g.plan, r, coalesce(pl.deposit_amount, 0), pl.orders_min, pl.orders_max, t.version, t.doc,
      jsonb_build_object('code', g.code, 'name', g.name, 'legal_name', g.legal_name, 'owner_name', g.owner_name, 'mobile', g.mobile, 'address', g.address, 'landmark', g.landmark, 'pincode', g.pincode, 'city', g.city, 'trade_id', g.trade_id, 'gstin', g.gstin, 'deposit_status', g.deposit_status, 'deposit_received_at', g.deposit_received_at),
      nm, left(p_ip_hash, 64), left(p_ua_hash, 64)) returning id into new_id;
  insert into public.audit_log (actor, action, details) values (null, 'agreement_signed_online', jsonb_build_object('garage', g.code, 'tier', g.plan, 'rate', r, 'terms_version', t.version));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.admin_agreement_signed(p_garage uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare s public.partner_agreements;
begin
  perform public.kyc_need_admin();
  select * into s from public.partner_agreements where garage_id = p_garage order by signed_at desc limit 1;
  if not found then return null; end if;
  return jsonb_build_object('tier', s.tier, 'rate', s.rate, 'plan', jsonb_build_object('commission_pct', s.rate, 'deposit_amount', s.deposit_amount, 'orders_min', s.orders_min, 'orders_max', s.orders_max), 'terms', s.terms, 'terms_version', s.terms_version, 'garage', s.garage, 'name', s.signed_name, 'at', s.signed_at);
end $$;

create or replace function public.garage_agreed_rate_set(p_id uuid, p_rate numeric) returns jsonb language plpgsql security definer set search_path = public as $$
declare g public.garages;
begin
  perform public.kyc_need_admin();
  if p_rate is null or p_rate <= 0 or p_rate > 100 then raise exception 'the rate must be above 0 and at most 100' using errcode = 'P0001'; end if;
  select * into g from public.garages where id = p_id and deleted_at is null; if not found then raise exception 'garage not found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.partner_agreements where garage_id = p_id) then raise exception 'the agreement is already signed, so the rate cannot be changed here' using errcode = 'P0001'; end if;
  update public.garages set agreed_rate = p_rate where id = p_id;
  insert into public.audit_log (actor, action, details) values (auth.uid(), 'garage_agreed_rate_set', jsonb_build_object('garage', g.code, 'rate', p_rate));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.admin_garage_get(p_id uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare g public.garages;
begin
  perform public.kyc_need_admin();
  select * into g from public.garages where id = p_id and deleted_at is null;
  if not found then raise exception 'garage not found' using errcode = 'P0002'; end if;
  return jsonb_build_object('garage', jsonb_build_object('id', g.id, 'code', g.code, 'name', g.name, 'legal_name', g.legal_name, 'trade_id', g.trade_id, 'gstin', g.gstin, 'agreed_rate', g.agreed_rate, 'owner_name', g.owner_name, 'mobile', g.mobile, 'address', g.address, 'landmark', g.landmark,
    'pincode', g.pincode, 'city', g.city, 'lat', g.lat, 'lng', g.lng, 'categories', g.categories, 'open_days', g.open_days, 'open_time', g.open_time, 'close_time', g.close_time, 'bays', g.bays, 'notes', g.notes,
    'plan', g.plan, 'deposit_status', g.deposit_status, 'deposit_received_at', g.deposit_received_at));
end $$;

revoke all on function public.partner_agreement_data(uuid), public.partner_agreement_sign(uuid, text, text, integer, text, text) from public, anon, authenticated;
grant execute on function public.partner_agreement_data(uuid), public.partner_agreement_sign(uuid, text, text, integer, text, text) to service_role;
revoke all on function public.admin_agreement_signed(uuid), public.garage_agreed_rate_set(uuid, numeric), public.admin_garage_get(uuid) from public, anon;
grant execute on function public.admin_agreement_signed(uuid), public.garage_agreed_rate_set(uuid, numeric), public.admin_garage_get(uuid) to authenticated;
